import pandas as pd

def predict(df: pd.DataFrame):
    # Block only COD orders with significant value
    # and either a promo code or a very high pincode RTO risk.
    return (
        (df['payment_mode'] == 'COD') &
        (df['order_value'] > 4000) &
        ((df['promo_code_used']) | (df['pincode_rolling_rto_rate'] > 0.6))
    )
